buggy.zero_td_times_inf:
import numpy as np
import pandas as pd

units = ["s", "ms", "us", "ns"]
factors = [np.inf, -np.inf, np.float32("inf")]

scalar_nat = 0
scalar_valueerror = 0
other = 0
vectorized_nat = 0

for unit in units:
    td = pd.Timedelta(0, unit)
    for factor in factors:
        ops = [lambda: td * factor, lambda: factor * td]
        for op in ops:
            try:
                res = op()
                if res is pd.NaT:
                    scalar_nat += 1
                else:
                    other += 1
            except ValueError:
                scalar_valueerror += 1
            except Exception:
                other += 1
        try:
            v = (pd.TimedeltaIndex([td]) * factor)[0]
            if v is pd.NaT:
                vectorized_nat += 1
            else:
                other += 1
        except Exception:
            other += 1

probe("scalar_nat", float(scalar_nat))
probe("scalar_valueerror", float(scalar_valueerror))
probe("other", float(other))
probe("vectorized_nat", float(vectorized_nat))

